CREATE OR REPLACE FUNCTION public.url_slug(_tekst text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT btrim(regexp_replace(lower(translate(btrim(coalesce(_tekst,'')),'ÀÁÂÃÄÅÈÉÊËÌÍÎÏÒÓÔÕÖÙÚÛÜÑàáâãäåèéêëìíîïòóôõöùúûüñ','aaaaaaeeeeiiiiooooouuuunaaaaaaeeeeiiiiooooouuuun')),'[^a-z0-9]+','-','g'),'-') $$;
CREATE OR REPLACE FUNCTION public.url_candidates(_key text DEFAULT NULL,_og text DEFAULT NULL) RETURNS TABLE(id uuid,uitvoerder public.case_uitvoerder,casenummer text,casenaam text,opdrachtgever text,behuizingsnummer text,naam_msr text,datum date,submitted_at timestamptz,created_at timestamptz) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$
 SELECT s.id,s.uitvoerder,s.casenummer,s.casenaam,s.opdrachtgever,s.behuizingsnummer,s.naam_msr,s.datum,s.submitted_at,s.created_at FROM public.stations s WHERE (_key IS NOT NULL AND (s.id::text=lower(_key) OR (public.url_slug(s.casenummer)<>'' AND (public.url_slug(_key)=public.url_slug(s.casenummer) OR public.url_slug(_key) LIKE public.url_slug(s.casenummer)||'-%')) OR lower(_key)=lower(concat_ws('-',nullif(regexp_replace(btrim(s.behuizingsnummer),'\s+','','g'),''),nullif(public.url_slug(s.naam_msr),''))) OR (nullif(regexp_replace(lower(btrim(s.behuizingsnummer)),'\s+','','g'),'') IS NOT NULL AND (lower(_key)=regexp_replace(lower(btrim(s.behuizingsnummer)),'\s+','','g') OR starts_with(lower(_key),regexp_replace(lower(btrim(s.behuizingsnummer)),'\s+','','g')||'-'))))) OR (_key IS NULL AND _og IS NOT NULL AND public.url_slug(coalesce(nullif(btrim(s.opdrachtgever),''),'van Gelder'))=public.url_slug(_og)) ORDER BY s.id
$$;
CREATE INDEX IF NOT EXISTS stations_url_case ON public.stations(public.url_slug(casenummer));
CREATE INDEX IF NOT EXISTS stations_url_opdrachtgever ON public.stations(public.url_slug(coalesce(nullif(btrim(opdrachtgever),''),'van Gelder')));